import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../services/auth.service';
import { UsersService } from '../services/users.service';
import { User } from '../models/user.model';

declare const bootstrap: any;

@Component({
  selector: 'app-users',
  templateUrl: './users.component.html',
})
export class UsersComponent implements OnInit {
  users: User[] = [];
  loading = false;
  error = '';
  successMsg = '';

  createForm!: FormGroup;
  saving = false;

  editingUser: User | null = null;
  editForm!: FormGroup;
  savingEdit = false;

  constructor(
    private fb: FormBuilder,
    private authService: AuthService,
    private usersService: UsersService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.createForm = this.fb.group({
      nombre: ['', [Validators.required, Validators.minLength(3)]],
      alias: ['', [Validators.required, Validators.minLength(3)]],
      role: ['user', Validators.required],
    });

    this.editForm = this.fb.group({
      nombre: ['', [Validators.required, Validators.minLength(3)]],
      alias: ['', [Validators.required, Validators.minLength(3)]],
      role: ['user', Validators.required],
      activo: [true],
    });

    this.loadUsers();
  }

  get currentUser(): User | null {
    return this.authService.currentUser;
  }

  loadUsers(): void {
    this.loading = true;
    this.usersService.getAll().subscribe({
      next: (data) => {
        this.users = data;
        this.loading = false;
      },
      error: () => {
        this.error = 'Error al cargar los usuarios';
        this.loading = false;
      },
    });
  }

  openCreate(): void {
    this.createForm.reset({ role: 'user' });
    const modal = new bootstrap.Modal(document.getElementById('createModal'));
    modal.show();
  }

  guardarUsuario(): void {
    if (this.createForm.invalid) {
      this.createForm.markAllAsTouched();
      return;
    }
    this.saving = true;
    this.usersService.create(this.createForm.value).subscribe({
      next: () => {
        this.saving = false;
        bootstrap.Modal.getInstance(document.getElementById('createModal'))?.hide();
        this.loadUsers();
        this.showSuccess('Usuario creado con contraseña predeterminada: usuario123');
      },
      error: (err) => {
        this.saving = false;
        this.error = err?.error?.message || 'Error al crear usuario';
      },
    });
  }

  openEdit(user: User): void {
    this.editingUser = user;
    this.editForm.patchValue({
      nombre: user.nombre,
      alias: user.alias,
      role: user.role,
      activo: user.activo,
    });
    const modal = new bootstrap.Modal(document.getElementById('editModal'));
    modal.show();
  }

  guardarEdicion(): void {
    if (this.editForm.invalid || !this.editingUser) {
      this.editForm.markAllAsTouched();
      return;
    }
    this.savingEdit = true;
    this.usersService.update(this.editingUser.id, this.editForm.value).subscribe({
      next: () => {
        this.savingEdit = false;
        bootstrap.Modal.getInstance(document.getElementById('editModal'))?.hide();
        this.loadUsers();
        this.showSuccess('Usuario actualizado');
      },
      error: (err) => {
        this.savingEdit = false;
        this.error = err?.error?.message || 'Error al actualizar usuario';
      },
    });
  }

  resetPassword(user: User): void {
    if (!confirm(`¿Restablecer la contraseña de "${user.nombre}" a "usuario123"?`)) return;
    this.usersService.resetPassword(user.id).subscribe({
      next: () => this.showSuccess(`Contraseña de ${user.nombre} restablecida a usuario123`),
      error: (err) => (this.error = err?.error?.message || 'Error al restablecer'),
    });
  }

  eliminarUsuario(user: User): void {
    if (user.id === this.currentUser?.id) {
      this.error = 'No puede eliminar su propio usuario';
      return;
    }
    if (!confirm(`¿Eliminar al usuario "${user.nombre}"?`)) return;
    this.usersService.delete(user.id).subscribe({
      next: () => {
        this.loadUsers();
        this.showSuccess('Usuario eliminado');
      },
      error: (err) => (this.error = err?.error?.message || 'Error al eliminar'),
    });
  }

  logout(): void {
    this.authService.logout();
  }

  private showSuccess(msg: string): void {
    this.successMsg = msg;
    setTimeout(() => (this.successMsg = ''), 5000);
  }
}
<!-- Navbar -->
<nav class="navbar navbar-expand-lg navbar-dark" style="background: #1e40af;">
  <div class="container-fluid px-4">
    <span class="navbar-brand">
      <i class="bi bi-people me-2"></i>Gestión de Usuarios
    </span>
    <div class="d-flex align-items-center gap-2 ms-auto">
      <button class="btn btn-outline-light btn-sm" routerLink="/dashboard">
        <i class="bi bi-arrow-left me-1"></i>Volver
      </button>
      <button class="btn btn-outline-light btn-sm" (click)="logout()">
        <i class="bi bi-box-arrow-right me-1"></i>Salir
      </button>
    </div>
  </div>
</nav>

<div class="container-fluid px-4 py-4">
  <!-- Alerts -->
  <div class="alert alert-success alert-dismissible py-2" *ngIf="successMsg">
    <i class="bi bi-check-circle me-1"></i>{{ successMsg }}
    <button type="button" class="btn-close py-2" (click)="successMsg = ''"></button>
  </div>
  <div class="alert alert-danger alert-dismissible py-2" *ngIf="error">
    <i class="bi bi-exclamation-circle me-1"></i>{{ error }}
    <button type="button" class="btn-close py-2" (click)="error = ''"></button>
  </div>

  <!-- Card usuarios -->
  <div class="card">
    <div class="card-header d-flex justify-content-between align-items-center">
      <h5 class="mb-0 fw-bold" style="color: #1e40af;">
        <i class="bi bi-people-fill me-2"></i>Listado de Usuarios
      </h5>
      <button class="btn btn-primary btn-sm" (click)="openCreate()">
        <i class="bi bi-person-plus me-1"></i>Nuevo Usuario
      </button>
    </div>

    <div class="text-center py-5" *ngIf="loading">
      <div class="spinner-border text-primary" role="status"></div>
    </div>

    <div class="table-responsive" *ngIf="!loading">
      <table class="table table-hover mb-0">
        <thead>
          <tr>
            <th>#</th>
            <th>Nombre</th>
            <th>Alias</th>
            <th>Rol</th>
            <th>Estado</th>
            <th>Fecha Creación</th>
            <th class="text-center">Acciones</th>
          </tr>
        </thead>
        <tbody>
          <tr *ngFor="let u of users">
            <td class="text-muted fw-bold">{{ u.id }}</td>
            <td>{{ u.nombre }}</td>
            <td><code>{{ u.alias }}</code></td>
            <td>
              <span class="badge bg-primary" *ngIf="u.role === 'admin'">Admin</span>
              <span class="badge bg-secondary" *ngIf="u.role === 'user'">Usuario</span>
            </td>
            <td>
              <span class="badge-si" *ngIf="u.activo">Activo</span>
              <span class="badge-no" *ngIf="!u.activo">Inactivo</span>
            </td>
            <td>{{ u.createdAt ? (u.createdAt | date:'dd/MM/yyyy') : '—' }}</td>
            <td class="text-center" style="white-space: nowrap;">
              <button
                class="btn btn-outline-secondary btn-sm me-1"
                title="Editar"
                (click)="openEdit(u)"
              >
                <i class="bi bi-pencil"></i>
              </button>
              <button
                class="btn btn-outline-warning btn-sm me-1"
                title="Restablecer Contraseña"
                (click)="resetPassword(u)"
              >
                <i class="bi bi-arrow-repeat"></i>
              </button>
              <button
                class="btn btn-outline-danger btn-sm"
                title="Eliminar"
                (click)="eliminarUsuario(u)"
                [disabled]="u.id === currentUser?.id"
              >
                <i class="bi bi-trash"></i>
              </button>
            </td>
          </tr>
          <tr *ngIf="users.length === 0">
            <td colspan="7" class="text-center text-muted py-4">No hay usuarios registrados</td>
          </tr>
        </tbody>
      </table>
    </div>
  </div>
</div>

<!-- ===== MODAL: Crear Usuario ===== -->
<div class="modal fade" id="createModal" tabindex="-1">
  <div class="modal-dialog">
    <div class="modal-content">
      <div class="modal-header">
        <h5 class="modal-title">
          <i class="bi bi-person-plus me-2"></i>Nuevo Usuario
        </h5>
        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
      </div>
      <div class="modal-body">
        <div class="alert alert-info py-2 small">
          <i class="bi bi-info-circle me-1"></i>
          La contraseña predeterminada será: <strong>usuario123</strong>
        </div>
        <form [formGroup]="createForm">
          <div class="mb-3">
            <label class="form-label fw-semibold">Nombre completo <span class="text-danger">*</span></label>
            <input
              type="text"
              class="form-control"
              formControlName="nombre"
              placeholder="Nombre del usuario"
            />
            <div class="text-danger small mt-1"
              *ngIf="createForm.get('nombre')?.touched && createForm.get('nombre')?.invalid">
              Mínimo 3 caracteres
            </div>
          </div>
          <div class="mb-3">
            <label class="form-label fw-semibold">Alias <span class="text-danger">*</span></label>
            <input
              type="text"
              class="form-control"
              formControlName="alias"
              placeholder="Alias para ingresar al sistema"
            />
            <div class="text-danger small mt-1"
              *ngIf="createForm.get('alias')?.touched && createForm.get('alias')?.invalid">
              Mínimo 3 caracteres
            </div>
          </div>
          <div class="mb-3">
            <label class="form-label fw-semibold">Rol <span class="text-danger">*</span></label>
            <select class="form-select" formControlName="role">
              <option value="user">Usuario</option>
              <option value="admin">Administrador</option>
            </select>
          </div>
        </form>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button>
        <button
          type="button"
          class="btn btn-primary"
          (click)="guardarUsuario()"
          [disabled]="saving"
        >
          <span *ngIf="saving" class="spinner-border spinner-border-sm me-1"></span>
          {{ saving ? 'Guardando...' : 'Crear Usuario' }}
        </button>
      </div>
    </div>
  </div>
</div>

<!-- ===== MODAL: Editar Usuario ===== -->
<div class="modal fade" id="editModal" tabindex="-1">
  <div class="modal-dialog">
    <div class="modal-content">
      <div class="modal-header">
        <h5 class="modal-title">
          <i class="bi bi-pencil me-2"></i>Editar Usuario
        </h5>
        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
      </div>
      <div class="modal-body">
        <form [formGroup]="editForm">
          <div class="mb-3">
            <label class="form-label fw-semibold">Nombre completo <span class="text-danger">*</span></label>
            <input type="text" class="form-control" formControlName="nombre" />
            <div class="text-danger small mt-1"
              *ngIf="editForm.get('nombre')?.touched && editForm.get('nombre')?.invalid">
              Mínimo 3 caracteres
            </div>
          </div>
          <div class="mb-3">
            <label class="form-label fw-semibold">Alias <span class="text-danger">*</span></label>
            <input type="text" class="form-control" formControlName="alias" />
            <div class="text-danger small mt-1"
              *ngIf="editForm.get('alias')?.touched && editForm.get('alias')?.invalid">
              Mínimo 3 caracteres
            </div>
          </div>
          <div class="mb-3">
            <label class="form-label fw-semibold">Rol</label>
            <select class="form-select" formControlName="role">
              <option value="user">Usuario</option>
              <option value="admin">Administrador</option>
            </select>
          </div>
          <div class="mb-3">
            <div class="form-check">
              <input class="form-check-input" type="checkbox" formControlName="activo" id="activoCheck" />
              <label class="form-check-label" for="activoCheck">Usuario activo</label>
            </div>
          </div>
        </form>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button>
        <button
          type="button"
          class="btn btn-primary"
          (click)="guardarEdicion()"
          [disabled]="savingEdit"
        >
          <span *ngIf="savingEdit" class="spinner-border spinner-border-sm me-1"></span>
          {{ savingEdit ? 'Guardando...' : 'Guardar Cambios' }}
        </button>
      </div>
    </div>
  </div>
</div>
